  if(event.key==='Tab'){const items=[...profilePopover.querySelectorAll('button:not(:disabled),a[href],summary')].filter(e=>e.getClientRects().length);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
