const openChatBase=openChat;openChat=f=>{const d=friendProfiles.get(f.uid);if(d)friendProfiles.set(f.uid,{...d,avatar:""});openChatBase(f);const shown=friendProfiles.get(f.uid)||f;$("#chat-title").textContent=shown.displayName||shown.username;$("#chat-title").onclick=()=>openProfileCard(f.uid,shown);$("#chat-title").tabIndex=0;$("#chat-title").setAttribute("role","button");$("#chat-title").onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();void openProfileCard(f.uid,shown)}};bindCosmetics(f.uid,null,$("#chat-title"))};
